//! MTP runtime pack reader (`MtpRtPack`: `dense.txt`, `dense.bin`, `experts.bin`, `draft_vocab.bin`).
//!
//! Matches the runtime artifact format generated by `tools/mtp_rt.py` and consumed by `src/core/mtp.cpp`.

use std::collections::BTreeMap;
use std::fs;
use std::path::{Path, PathBuf};

use talus_core_api::DraftVocab;

use crate::draft_vocab::DraftVocabFile;
use crate::error::{GgufError, Result};
use crate::mmap::{Backing, Mmap};

/// Byte size of one Q2_0 routed expert blob (`gate || up || down`) in `mtp/rt/experts.bin`:
/// `3 * 640 * (2560 / 32) * 9 = 1,382,400` bytes.
pub const MTP_EXPERT_BLOB_BYTES: usize = 3 * 640 * (2560 / 32) * 9;

/// Required tensor names in `mtp/rt/dense.txt` (from `src/core/mtp.cpp`).
pub const MTP_REQUIRED_DENSE_TENSORS: &[&str] = &[
    "fc_embedding.weight",
    "fc_hidden.weight",
    "self_attn.q_proj.weight",
    "self_attn.k_proj.weight",
    "self_attn.v_proj.weight",
    "self_attn.o_proj.weight",
    "mlp.shared_expert.gate_proj.weight",
    "mlp.shared_expert.up_proj.weight",
    "mlp.shared_expert.down_proj.weight",
    "enorm.weight",
    "hnorm.weight",
    "input_layernorm.weight",
    "self_attn.q_norm.weight",
    "self_attn.k_norm.weight",
    "post_attention_layernorm.weight",
    "mlp.gate.weight",
    "mlp.shared_expert_gate.weight",
    "norm.weight",
];

/// Data type tag in `mtp/rt/dense.txt`.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum MtpTensorKind {
    /// `"q8_0"`: 34 bytes per 32 elements (`half d + int8 qs[32]`).
    Q8_0,
    /// `"bf16"`: 2 bytes per element.
    Bf16,
    /// `"f32"`: 4 bytes per element.
    F32,
}

impl MtpTensorKind {
    /// Parses a tensor kind string (`"q8_0"`, `"bf16"`, or `"f32"`).
    pub fn from_name(s: &str) -> Option<Self> {
        match s {
            "q8_0" => Some(Self::Q8_0),
            "bf16" => Some(Self::Bf16),
            "f32" => Some(Self::F32),
            _ => None,
        }
    }

    /// Canonical string name in `dense.txt`.
    pub const fn as_str(self) -> &'static str {
        match self {
            Self::Q8_0 => "q8_0",
            Self::Bf16 => "bf16",
            Self::F32 => "f32",
        }
    }

    /// Computes expected byte size for `(rows, cols)`.
    pub const fn expected_bytes(self, rows: u64, cols: u64) -> Option<u64> {
        if rows == 0 || cols == 0 {
            return None;
        }
        match self {
            Self::Q8_0 => {
                if !cols.is_multiple_of(32) {
                    return None;
                }
                let blocks_per_row = cols / 32;
                let Some(row_bytes) = blocks_per_row.checked_mul(34) else {
                    return None;
                };
                rows.checked_mul(row_bytes)
            }
            Self::Bf16 => {
                let Some(elems) = rows.checked_mul(cols) else {
                    return None;
                };
                elems.checked_mul(2)
            }
            Self::F32 => {
                let Some(elems) = rows.checked_mul(cols) else {
                    return None;
                };
                elems.checked_mul(4)
            }
        }
    }
}

/// Entry parsed from `mtp/rt/dense.txt`: `<name> <kind> <rows> <cols> <offset> <bytes>`.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct MtpDenseTensor {
    pub name: String,
    pub kind: MtpTensorKind,
    pub rows: u64,
    pub cols: u64,
    pub offset: u64,
    pub bytes: u64,
}

/// Reader for an MTP runtime directory (`dense.txt`, `dense.bin`, optional `experts.bin` and `draft_vocab.bin`).
#[derive(Debug)]
pub struct MtpRtPack {
    rt_dir: Option<PathBuf>,
    tensors: Vec<MtpDenseTensor>,
    by_name: BTreeMap<String, usize>,
    dense_bin: Option<Backing>,
    experts_bin: Option<Backing>,
    draft_vocab: Option<DraftVocab>,
}

impl MtpRtPack {
    /// Opens an MTP `rt/` directory, parsing `dense.txt`, mapping `dense.bin`, and optionally
    /// mapping `experts.bin` and loading `draft_vocab.bin` if present.
    pub fn open(rt_dir: impl AsRef<Path>) -> Result<Self> {
        let dir = rt_dir.as_ref().to_path_buf();
        let dense_txt_path = dir.join("dense.txt");
        let dense_txt = fs::read_to_string(&dense_txt_path).map_err(|e| GgufError::MtpFormat {
            message: format!("cannot open {}: {e}", dense_txt_path.display()),
        })?;
        let (tensors, by_name) = Self::parse_dense_index(&dense_txt)?;

        let dense_bin_path = dir.join("dense.bin");
        let dense_bin = if dense_bin_path.is_file() {
            let mm = Mmap::open(&dense_bin_path)?;
            validate_dense_bounds(&tensors, mm.len() as u64)?;
            Some(Backing::Mmap(mm))
        } else {
            None
        };

        let experts_bin_path = dir.join("experts.bin");
        let experts_bin = if experts_bin_path.is_file() {
            let mm = Mmap::open(&experts_bin_path)?;
            if mm.is_empty() || !mm.len().is_multiple_of(MTP_EXPERT_BLOB_BYTES) {
                return Err(GgufError::MtpFormat {
                    message: format!(
                        "experts.bin size {} is not a positive multiple of expert blob size {}",
                        mm.len(),
                        MTP_EXPERT_BLOB_BYTES
                    ),
                });
            }
            Some(Backing::Mmap(mm))
        } else {
            None
        };

        let draft_vocab_path = dir.join("draft_vocab.bin");
        let draft_vocab = if draft_vocab_path.is_file() {
            Some(DraftVocabFile::open(&draft_vocab_path)?)
        } else {
            None
        };

        Ok(Self {
            rt_dir: Some(dir),
            tensors,
            by_name,
            dense_bin,
            experts_bin,
            draft_vocab,
        })
    }

    /// Constructs an [`MtpRtPack`] from an in-memory `dense.txt` manifest and optional `dense.bin` bytes.
    pub fn from_bytes(dense_txt: &str, dense_bin: Option<Vec<u8>>) -> Result<Self> {
        let (tensors, by_name) = Self::parse_dense_index(dense_txt)?;
        if let Some(ref bin) = dense_bin {
            validate_dense_bounds(&tensors, bin.len() as u64)?;
        }
        Ok(Self {
            rt_dir: None,
            tensors,
            by_name,
            dense_bin: dense_bin.map(Backing::Owned),
            experts_bin: None,
            draft_vocab: None,
        })
    }

    /// Parses the `dense.txt` index table without requiring `dense.bin`.
    pub fn parse_dense_index(text: &str) -> Result<(Vec<MtpDenseTensor>, BTreeMap<String, usize>)> {
        let mut tensors = Vec::new();
        let mut by_name = BTreeMap::new();

        for (line_no, raw_line) in text.lines().enumerate() {
            let line = raw_line.trim();
            if line.is_empty() || line.starts_with('#') {
                continue;
            }
            let fields: Vec<&str> = line.split_whitespace().collect();
            if fields.len() != 6 {
                return Err(GgufError::MtpFormat {
                    message: format!(
                        "dense.txt line {}: expected 6 fields (<name> <kind> <rows> <cols> <offset> <bytes>), got {}",
                        line_no + 1,
                        fields.len()
                    ),
                });
            }
            let name = fields[0].to_string();
            let kind = MtpTensorKind::from_name(fields[1]).ok_or_else(|| GgufError::MtpFormat {
                message: format!(
                    "dense.txt line {}: unknown tensor kind '{}' for '{name}'",
                    line_no + 1,
                    fields[1]
                ),
            })?;
            let rows: u64 = fields[2].parse().map_err(|_| GgufError::MtpFormat {
                message: format!(
                    "dense.txt line {}: invalid rows '{}'",
                    line_no + 1,
                    fields[2]
                ),
            })?;
            let cols: u64 = fields[3].parse().map_err(|_| GgufError::MtpFormat {
                message: format!(
                    "dense.txt line {}: invalid cols '{}'",
                    line_no + 1,
                    fields[3]
                ),
            })?;
            let offset: u64 = fields[4].parse().map_err(|_| GgufError::MtpFormat {
                message: format!(
                    "dense.txt line {}: invalid offset '{}'",
                    line_no + 1,
                    fields[4]
                ),
            })?;
            let bytes: u64 = fields[5].parse().map_err(|_| GgufError::MtpFormat {
                message: format!(
                    "dense.txt line {}: invalid bytes '{}'",
                    line_no + 1,
                    fields[5]
                ),
            })?;

            let expected = kind
                .expected_bytes(rows, cols)
                .ok_or_else(|| GgufError::MtpFormat {
                    message: format!(
                        "dense.txt line {}: invalid shape ({rows}, {cols}) for {} tensor '{name}'",
                        line_no + 1,
                        kind.as_str()
                    ),
                })?;
            if bytes != expected {
                return Err(GgufError::MtpFormat {
                    message: format!(
                        "dense.txt line {}: tensor '{name}' ({}, {rows}x{cols}) declares {bytes} B, expected {expected} B",
                        line_no + 1,
                        kind.as_str()
                    ),
                });
            }

            if by_name.insert(name.clone(), tensors.len()).is_some() {
                return Err(GgufError::MtpFormat {
                    message: format!("duplicate tensor '{name}' in dense.txt"),
                });
            }
            tensors.push(MtpDenseTensor {
                name,
                kind,
                rows,
                cols,
                offset,
                bytes,
            });
        }

        if tensors.is_empty() {
            return Err(GgufError::MtpFormat {
                message: "dense.txt contains no tensor entries".to_string(),
            });
        }

        Ok((tensors, by_name))
    }

    /// Directory path if opened from disk.
    #[inline]
    pub fn rt_dir(&self) -> Option<&Path> {
        self.rt_dir.as_deref()
    }

    /// All parsed tensor entries in `dense.txt` order.
    #[inline]
    pub fn tensors(&self) -> &[MtpDenseTensor] {
        &self.tensors
    }

    /// Looks up a tensor entry by name.
    #[inline]
    pub fn find(&self, name: &str) -> Option<&MtpDenseTensor> {
        self.by_name.get(name).map(|&i| &self.tensors[i])
    }

    /// Returns the zero-copy byte slice in `dense.bin` for tensor `name`.
    pub fn tensor_bytes(&self, name: &str) -> Result<&[u8]> {
        let entry = self.find(name).ok_or_else(|| GgufError::TensorNotFound {
            name: name.to_string(),
        })?;
        let dense = self
            .dense_bin
            .as_ref()
            .ok_or_else(|| GgufError::MtpFormat {
                message: "dense.bin is not loaded".to_string(),
            })?;
        let start = entry.offset as usize;
        let end = start + (entry.bytes as usize);
        if end > dense.len() {
            return Err(GgufError::MtpFormat {
                message: format!(
                    "MTP tensor '{name}' span [{start}..{end}) exceeds dense.bin size {}",
                    dense.len()
                ),
            });
        }
        Ok(&dense.as_slice()[start..end])
    }

    /// Verifies that all 18 required Qwen3.8-Flash-Next MTP dense tensors are present in `dense.txt`.
    pub fn validate_required_tensors(&self) -> Result<()> {
        for &req in MTP_REQUIRED_DENSE_TENSORS {
            if !self.by_name.contains_key(req) {
                return Err(GgufError::MtpFormat {
                    message: format!("missing required MTP tensor '{req}' in dense.txt"),
                });
            }
        }
        Ok(())
    }

    /// Number of routed experts stored in `experts.bin` (if mapped).
    #[inline]
    pub fn expert_count(&self) -> Option<usize> {
        self.experts_bin
            .as_ref()
            .map(|b| b.len() / MTP_EXPERT_BLOB_BYTES)
    }

    /// Returns the 1,382,400-byte Q2_0 blob for `expert` from `experts.bin`.
    pub fn expert_blob_bytes(&self, expert: usize) -> Result<&[u8]> {
        let exp = self
            .experts_bin
            .as_ref()
            .ok_or_else(|| GgufError::MtpFormat {
                message: "experts.bin is not loaded".to_string(),
            })?;
        let count = exp.len() / MTP_EXPERT_BLOB_BYTES;
        if expert >= count {
            return Err(GgufError::MtpFormat {
                message: format!("MTP expert {expert} out of range 0..{count}"),
            });
        }
        let start = expert * MTP_EXPERT_BLOB_BYTES;
        let end = start + MTP_EXPERT_BLOB_BYTES;
        Ok(&exp.as_slice()[start..end])
    }

    /// Optional draft vocabulary loaded from `draft_vocab.bin` in `rt_dir`.
    #[inline]
    pub fn draft_vocab(&self) -> Option<&DraftVocab> {
        self.draft_vocab.as_ref()
    }
}

fn validate_dense_bounds(tensors: &[MtpDenseTensor], dense_len: u64) -> Result<()> {
    for t in tensors {
        let end = t
            .offset
            .checked_add(t.bytes)
            .ok_or_else(|| GgufError::MtpFormat {
                message: format!("offset overflow for MTP tensor '{}'", t.name),
            })?;
        if end > dense_len {
            return Err(GgufError::MtpFormat {
                message: format!(
                    "MTP tensor '{}' span [{}..{end}) exceeds dense.bin size {dense_len}",
                    t.name, t.offset
                ),
            });
        }
    }
    Ok(())
}
